use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse};
use serde::Deserialize;
use std::collections::HashMap;
use tera::{Tera, Context};

#[derive(Deserialize)]
struct TemplateRequest {
    name: String,
    greeting_template: String,
}

// Renders a user-customizable greeting card
async fn render_greeting(
    req: HttpRequest,
    body: web::Json<TemplateRequest>,
    tera: web::Data<Tera>,
) -> HttpResponse {
    // Log the requesting IP for audit purposes
    let peer = req.peer_addr()
        .map(|a| a.ip().to_string())
        .unwrap_or_else(|| "unknown".to_string());
    log::info!("Greeting render request from: {}", peer);

    // Build context with user-supplied name
    let mut context = Context::new();
    context.insert("name", &body.name);
    context.insert("year", &2024);

    // VULNERABILITY: User-supplied template string is rendered directly
    // Tera supports calling macros, accessing variables, and filter chains
    // An attacker can inject template directives to read context or cause DoS
    let template_source = format!(
        "{{% raw %}}<!-- greeting card -->{{% endraw %}}\n{}",
        body.greeting_template
    );

    match tera.render_str(&template_source, &context) {
        Ok(rendered) => {
            HttpResponse::Ok()
                .content_type("text/html; charset=utf-8")
                .body(rendered)
        }
        Err(e) => {
            log::error!("Template render error: {:?}", e);
            HttpResponse::BadRequest()
                .body(format!("Template error: {}", e))
        }
    }
}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().body("OK")
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();

    let tera = Tera::default();

    log::info!("Starting greeting card service on 0.0.0.0:8080");

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(tera.clone()))
            .route("/health", web::get().to(health_check))
            .route("/api/v1/greeting", web::post().to(render_greeting))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}

#[cfg(test)]
mod tests {
    use super::*;
    use actix_web::test;

    #[actix_web::test]
    async fn test_normal_greeting() {
        let tera = Tera::default();
        let app = test::init_service(
            App::new()
                .app_data(web::Data::new(tera))
                .route("/api/v1/greeting", web::post().to(render_greeting))
        ).await;

        let req = test::TestRequest::post()
            .uri("/api/v1/greeting")
            .set_json(&serde_json::json!({
                "name": "Alice",
                "greeting_template": "<h1>Hello {{ name }}!</h1>"
            }))
            .to_request();

        let resp = test::call_service(&app, req).await;
        assert!(resp.status().is_success());
    }
}
